select 'functions' c, count(*) n, md5(coalesce(string_agg(x, E'\n' order by x),'')) h from (select p.oid::regprocedure::text||'|'||md5(pg_get_functiondef(p.oid))||'|'||coalesce(p.proacl::text,'') x from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','internal','saas')) s
union all select 'columns', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select table_schema||'.'||table_name||'.'||column_name||'|'||data_type||'|'||is_nullable||'|'||coalesce(column_default,'')||'|'||udt_name x from information_schema.columns where table_schema in ('public','internal','saas')) s
union all select 'constraints', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select conrelid::regclass::text||'|'||conname||'|'||pg_get_constraintdef(oid) x from pg_constraint where connamespace::regnamespace::text in ('public','internal','saas')) s
union all select 'triggers', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select tgrelid::regclass::text||'|'||pg_get_triggerdef(t.oid) x from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace::regnamespace::text in ('public','internal','saas') and not t.tgisinternal) s
union all select 'policies', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select schemaname||'.'||tablename||'.'||policyname||'|'||permissive||'|'||roles::text||'|'||cmd||'|'||coalesce(qual,'')||'|'||coalesce(with_check,'') x from pg_policies where schemaname in ('public','internal','saas')) s
union all select 'indexes', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select schemaname||'|'||indexdef x from pg_indexes where schemaname in ('public','internal','saas')) s
union all select 'table_grants', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select table_schema||'.'||table_name||'.'||grantee||'.'||privilege_type x from information_schema.role_table_grants where table_schema in ('public','internal','saas')) s
union all select 'views', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select schemaname||'.'||viewname||'|'||md5(definition) x from pg_views where schemaname in ('public','internal','saas')) s
union all select 'enums', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select t.typname||'|'||string_agg(e.enumlabel, ',' order by e.enumsortorder) x from pg_type t join pg_enum e on e.enumtypid=t.oid join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','internal','saas') group by t.typname) s;
